/** A returned-row limit cannot bound a large directory or the tombstones hidden inside iterator advancement. */
@Isolated
@Timeout(180)
class LmdbPersistentCardinalityPhysicalWorkTest {

	private static final long SUBJECT = 10;
	private static final long OBJECT = 900_000;
	private static final long FIRST_PREDICATE = 1_000;
	private static final long MATCHING_CONTEXT = 7;
	private static final long OTHER_CONTEXT = 8;
	private static final int SMALL_DEGREE = 8_192;
	private static final int TOMBSTONE_PREDICATES = 64;
	private static final int TARGET_ROWS = 120;
	private static final long MAX_NATIVE_READS = 4_096;
	private static final long MAX_PAGE_WALKS = 2L * (Statistics.MAX_BUCKETS + 2);

	@TempDir
	Path directory;

	@ParameterizedTest
	@ValueSource(booleans = { true, false })
	void subjectAndObjectDirectoryWorkIsBoundedAsDegreeDoubles(boolean enabled) throws Exception {
		try (PropertySetting ignored = new PropertySetting();
				TripleStore store = new TripleStore(directory.toFile(), config(enabled), null)) {
			appendDirectoryRows(store, 0, SMALL_DEGREE);
			assertDirectoryShape(store, SMALL_DEGREE);
			Observation smallSubject = observe(store, SUBJECT, -1, -1, -1);
			Observation smallObject = observe(store, -1, -1, OBJECT, -1);
			assertDirectoryQueries(store, SMALL_DEGREE);
			appendDirectoryRows(store, SMALL_DEGREE, SMALL_DEGREE);
			assertDirectoryShape(store, 2 * SMALL_DEGREE);
			Observation largeSubject = observe(store, SUBJECT, -1, -1, -1);
			Observation largeObject = observe(store, -1, -1, OBJECT, -1);
			// Run independent exact controls after all estimates, even on the original unbounded implementation.
			assertDirectoryQueries(store, 2 * SMALL_DEGREE);
			assertDirectoryEstimate(smallSubject, 2L * SMALL_DEGREE, 0, 2);
			assertDirectoryEstimate(smallObject, 2L * SMALL_DEGREE, 1, 3);
			assertDirectoryEstimate(largeSubject, 4L * SMALL_DEGREE, 0, 2);
			assertDirectoryEstimate(largeObject, 4L * SMALL_DEGREE, 1, 3);
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { true, false })
	void lateLiveMatchDoesNotHideUnboundedTombstoneAdvancement(boolean enabled) throws Exception {
		try (PropertySetting ignored = new PropertySetting()) {
			try (TripleStore store = new TripleStore(directory.toFile(), config(enabled), null)) {
				writeTombstoneBase(store);
				store.startTransaction();
				int[] removed = { 0 };
				for (boolean explicit : new boolean[] { true, false }) {
					for (int predicate = 0; predicate < TOMBSTONE_PREDICATES; predicate++) {
						for (int row = 0; row < TARGET_ROWS - 1; row++) {
							store.removeTriplesByContext(SUBJECT, FIRST_PREDICATE + predicate, OBJECT + row,
									OTHER_CONTEXT, explicit, quad -> removed[0]++);
						}
					}
				}
				assertThat(removed[0]).isEqualTo(2 * TOMBSTONE_PREDICATES * (TARGET_ROWS - 1));
				// 119 deltas per predicate/plane stays below the 128-entry automatic compaction threshold.
				store.commit();
				assertTombstoneShape(store);
			}
			try (TripleStore reopened = new TripleStore(directory.toFile(), config(enabled), null)) {
				assertTombstoneShape(reopened);
				Observation estimate = observe(reopened, SUBJECT, -1, -1, MATCHING_CONTEXT);
				// All earlier target rows are deleted or fail C; the only live match is in the last predicate.
				try (Txn txn = reopened.getTxnManager().createReadTxn()) {
					for (boolean explicit : new boolean[] { true, false }) {
						try (RecordIterator rows = reopened.getTriples(txn, SUBJECT, -1, -1,
								MATCHING_CONTEXT, explicit)) {
							assertThat(rows.next()).containsExactly(SUBJECT,
									FIRST_PREDICATE + TOMBSTONE_PREDICATES - 1, OBJECT + TARGET_ROWS - 1,
									MATCHING_CONTEXT);
							assertThat(rows.next()).isNull();
						}
						assertThat(count(reopened, txn, -1, -1, -1, -1, explicit))
								.isEqualTo(2L * TOMBSTONE_PREDICATES);
					}
				}
				assertThat(reopened.cardinality(-1, -1, -1, -1)).isEqualTo(4D * TOMBSTONE_PREDICATES);
				assertThat(reopened.cardinality(-1, -1, -1, MATCHING_CONTEXT))
						.isEqualTo(2D * (TOMBSTONE_PREDICATES + 1));
				assertBounded(estimate, 2L * (TOMBSTONE_PREDICATES + 1));
				assertThat(estimate.estimate()).as("a positive live match must not become a sampled exact zero")
						.isPositive();
				assertThat(estimate.absentPlanes()).as("real ABSENT values, not a fabricated iterator counter")
						.containsExactlyInAnyOrder(0, 2);
				assertThat(estimate.decodedPages()).as("actual packed base values are projected alongside deltas")
						.isPositive();
			}
		}
	}

	private static LmdbStoreConfig config(boolean enabled) {
		return new LmdbStoreConfig("spoc,posc").setPageCardinalityEstimator(enabled)
				.setSketchEstimatorEnabled(false)
				.setAutoGrow(false)
				.setTripleDBSize(128L << 20);
	}

	private static void appendDirectoryRows(TripleStore store, int first, int count) throws IOException {
		long[] subjects = new long[count];
		long[] predicates = new long[count];
		long[] objects = new long[count];
		long[] contexts = new long[count];
		Arrays.fill(subjects, SUBJECT);
		Arrays.fill(objects, OBJECT);
		Arrays.fill(contexts, OTHER_CONTEXT);
		for (int row = 0; row < count; row++) {
			predicates[row] = FIRST_PREDICATE + first + row;
		}
		store.startTransaction();
		// Insert explicit first, then inferred, so both independent logical planes retain the same quad.
		for (boolean explicit : new boolean[] { true, false }) {
			store.storeTriplesAligned(subjects, predicates, objects, contexts, count, explicit);
		}
		LmdbPersistentAdjacency.openExisting(store.writeTxn).compact(store.writeTxn, true);
		store.commit();
	}

	private static void writeTombstoneBase(TripleStore store) throws IOException {
		int count = TOMBSTONE_PREDICATES * (TARGET_ROWS + 1);
		long[] subjects = new long[count];
		long[] predicates = new long[count];
		long[] objects = new long[count];
		long[] contexts = new long[count];
		int index = 0;
		for (int predicate = 0; predicate < TOMBSTONE_PREDICATES; predicate++) {
			for (int row = 0; row < TARGET_ROWS; row++, index++) {
				subjects[index] = SUBJECT;
				predicates[index] = FIRST_PREDICATE + predicate;
				objects[index] = OBJECT + row;
				contexts[index] = predicate == TOMBSTONE_PREDICATES - 1 && row == TARGET_ROWS - 1
						? MATCHING_CONTEXT
						: OTHER_CONTEXT;
			}
			subjects[index] = SUBJECT + 1;
			predicates[index] = FIRST_PREDICATE + predicate;
			objects[index] = OBJECT + TARGET_ROWS;
			contexts[index++] = MATCHING_CONTEXT;
		}
		store.startTransaction();
		for (boolean explicit : new boolean[] { true, false }) {
			store.storeTriplesAligned(subjects, predicates, objects, contexts, count, explicit);
		}
		LmdbPersistentAdjacency.openExisting(store.writeTxn).compact(store.writeTxn, true);
		store.commit();
	}

	private static void assertDirectoryQueries(TripleStore store, int degree) throws IOException {
		try (Txn txn = store.getTxnManager().createReadTxn()) {
			for (boolean explicit : new boolean[] { true, false }) {
				assertThat(count(store, txn, SUBJECT, -1, -1, -1, explicit)).isEqualTo(degree);
				assertThat(count(store, txn, -1, -1, OBJECT, -1, explicit)).isEqualTo(degree);
			}
		}
		assertThat(store.cardinality(-1, -1, -1, -1)).isEqualTo(2D * degree);
	}

	private static long count(TripleStore store, Txn txn, long subject, long predicate, long object, long context,
			boolean explicit) throws IOException {
		long count = 0;
		try (RecordIterator rows = store.getTriples(txn, subject, predicate, object, context, explicit)) {
			while (rows.next() != null) {
				count++;
			}
		}
		return count;
	}

	private static void assertDirectoryShape(TripleStore store, int degree) throws IOException {
		long[] records = new long[4];
		try (Txn txn = store.getTxnManager().createReadTxn()) {
			LmdbPersistentAdjacency adjacency = LmdbPersistentAdjacency.openExisting(txn.get());
			visit(txn.get(), adjacency.metadataDbi(), (key, value) -> {
				if (key.remaining() == 18 && key.get(0) == 4) {
					int plane = Byte.toUnsignedInt(key.get(1));
					assertThat(plane).isBetween(0, 3);
					assertThat(key.getLong(2)).isEqualTo((plane & 1) == 0 ? SUBJECT : OBJECT);
					assertThat(key.getLong(10)).isBetween(FIRST_PREDICATE, FIRST_PREDICATE + degree - 1);
					assertThat(value.remaining()).isEqualTo(Long.BYTES);
					assertThat(value.getLong(0)).isEqualTo(1L);
					records[plane]++;
				}
			});
		}
		assertThat(records).containsExactly(degree, degree, degree, degree);
	}

	private static void assertTombstoneShape(TripleStore store) throws IOException {
		long[] pages = new long[4];
		long[] absent = new long[4];
		try (Txn txn = store.getTxnManager().createReadTxn()) {
			LmdbPersistentAdjacency adjacency = LmdbPersistentAdjacency.openExisting(txn.get());
			visit(txn.get(), adjacency.pagesDbi(), (key, value) -> {
				int plane = edgePlane(key);
				assertThat(PersistentCsfPageCodec.decode(value).size()).isEqualTo(TARGET_ROWS + 1);
				pages[plane]++;
			});
			visit(txn.get(), adjacency.deltasDbi(), (key, value) -> {
				int plane = edgePlane(key);
				assertThat(value.remaining()).isEqualTo(1);
				assertThat(value.get(0)).isZero();
				absent[plane]++;
			});
		}
		long tombstones = (long) TOMBSTONE_PREDICATES * (TARGET_ROWS - 1);
		assertThat(pages).containsExactly(TOMBSTONE_PREDICATES, TOMBSTONE_PREDICATES,
				TOMBSTONE_PREDICATES, TOMBSTONE_PREDICATES);
		assertThat(absent).containsExactly(tombstones, tombstones, tombstones, tombstones);
	}

	private static int edgePlane(ByteBuffer key) {
		assertThat(key.remaining()).isEqualTo(33);
		int plane = Byte.toUnsignedInt(key.get(0));
		assertThat(plane).isBetween(0, 3);
		assertThat(key.getLong(1)).isBetween(FIRST_PREDICATE,
				FIRST_PREDICATE + TOMBSTONE_PREDICATES - 1);
		return plane;
	}

	private static void visit(long txn, int database, NativeEntryVisitor visitor) throws IOException {
		try (MemoryStack stack = stackPush()) {
			PointerBuffer handle = stack.mallocPointer(1);
			E(mdb_cursor_open(txn, database, handle));
			long cursor = handle.get(0);
			try {
				MDBVal key = MDBVal.calloc(stack);
				MDBVal value = MDBVal.calloc(stack);
				int rc = mdb_cursor_get(cursor, key, value, MDB_FIRST);
				while (rc == MDB_SUCCESS) {
					visitor.accept(key.mv_data().duplicate().order(ByteOrder.BIG_ENDIAN),
							value.mv_data().duplicate().order(ByteOrder.BIG_ENDIAN));
					rc = mdb_cursor_get(cursor, key, value, MDB_NEXT);
				}
				if (rc != MDB_NOTFOUND) {
					E(rc);
				}
			} finally {
				mdb_cursor_close(cursor);
			}
		}
	}

	private static Observation observe(TripleStore store, long subject, long predicate, long object, long context)
			throws IOException {
		long expectedTxnId;
		int metadataDbi;
		int deltasDbi;
		try (Txn txn = store.getTxnManager().createReadTxn()) {
			expectedTxnId = mdb_txn_id(txn.get());
			LmdbPersistentAdjacency adjacency = LmdbPersistentAdjacency.openExisting(txn.get());
			metadataDbi = adjacency.metadataDbi();
			deltasDbi = adjacency.deltasDbi();
		}
		try (NativeWork work = new NativeWork(metadataDbi, deltasDbi, subject != -1 ? subject : object,
				subject != -1 ? 0 : 1)) {
			double estimate = store.cardinality(subject, predicate, object, context);
			return new Observation(estimate, expectedTxnId, Set.copyOf(work.readerTxnIds),
					Set.copyOf(work.readerHandles), work.pointReads,
					work.cursorReads, work.decodedPages, work.decodedRows, work.probedPages,
					Set.copyOf(work.directoryPlanes), Set.copyOf(work.absentPlanes));
		}
	}

	private static void assertDirectoryEstimate(Observation observation, long upper, Integer... planes) {
		assertBounded(observation, upper);
		assertThat(observation.estimate()).isPositive();
		assertThat(observation.directoryPlanes()).as("real NODE_PREDICATE scalar values in both requested planes")
				.containsExactlyInAnyOrder(planes);
		assertThat(observation.decodedPages() + observation.probedPages())
				.as("a node directory estimate does not need to decode its statement population")
				.isZero();
	}

	private static void assertBounded(Observation observation, long upper) {
		System.out.printf("persistent-cardinality-physical-work observation=%s upper=%d%n", observation, upper);
		assertThat(observation.estimate()).isFinite().isBetween(0D, (double) upper);
		assertThat(observation.readerTxnIds()).containsExactly(observation.expectedTxnId());
		assertThat(observation.readerHandles()).as("one borrowed native transaction throughout the estimate")
				.hasSize(1);
		assertThat(observation.pointReads() + observation.cursorReads()).isPositive()
				.isLessThanOrEqualTo(MAX_NATIVE_READS);
		assertThat(observation.decodedPages() + observation.probedPages()).isLessThanOrEqualTo(MAX_PAGE_WALKS);
		assertThat(observation.decodedRows())
				.isLessThanOrEqualTo(MAX_PAGE_WALKS * PersistentCsfPageCodec.MAX_PAIRS);
	}

	@FunctionalInterface
	private interface NativeEntryVisitor {
		void accept(ByteBuffer key, ByteBuffer value) throws IOException;
	}

	private record Observation(double estimate, long expectedTxnId, Set<Long> readerTxnIds, Set<Long> readerHandles,
			long pointReads,
			long cursorReads, long decodedPages, long decodedRows, long probedPages,
			Set<Integer> directoryPlanes, Set<Integer> absentPlanes) {
	}

	private static final class PropertySetting implements AutoCloseable {
		private final String previous = System.getProperty(TripleStore.DISABLE_PAGE_WALKING_ESTIMATOR_PROPERTY);

		PropertySetting() {
			System.setProperty(TripleStore.DISABLE_PAGE_WALKING_ESTIMATOR_PROPERTY, "false");
		}

		@Override
		public void close() {
			if (previous == null) {
				System.clearProperty(TripleStore.DISABLE_PAGE_WALKING_ESTIMATOR_PROPERTY);
			} else {
				System.setProperty(TripleStore.DISABLE_PAGE_WALKING_ESTIMATOR_PROPERTY, previous);
			}
		}
	}

	/** Every observed result is the real call; overload-depth guards count each native/codec operation once. */
	private static final class NativeWork implements AutoCloseable {
		private final MockedStatic<LMDB> nativeCalls;
		private final MockedStatic<PersistentCsfPageCodec> codecCalls;
		private final Map<Long, Integer> cursorDatabases = new HashMap<>();
		private final Set<Long> readerTxnIds = new HashSet<>();
		private final Set<Long> readerHandles = new HashSet<>();
		private final Set<Integer> directoryPlanes = new HashSet<>();
		private final Set<Integer> absentPlanes = new HashSet<>();
		private int nativeDepth;
		private int codecDepth;
		private long pointReads;
		private long cursorReads;
		private long decodedPages;
		private long decodedRows;
		private long probedPages;

		NativeWork(int metadataDbi, int deltasDbi, long directoryNode, int direction) {
			nativeCalls = mockStatic(LMDB.class, invocation -> {
				boolean outermost = nativeDepth++ == 0;
				try {
					String method = invocation.getMethod().getName();
					if (outermost && method.equals("mdb_get")) {
						pointReads++;
						long txn = invocation.getArgument(0);
						readerHandles.add(txn);
						readerTxnIds.add(mdb_txn_id(txn));
					} else if (outermost && method.equals("mdb_cursor_get")) {
						cursorReads++;
					} else if (outermost && method.equals("mdb_cursor_open")) {
						long txn = invocation.getArgument(0);
						readerHandles.add(txn);
						readerTxnIds.add(mdb_txn_id(txn));
					}
					Object result = invocation.callRealMethod();
					if (outermost && result instanceof Integer rc && rc == MDB_SUCCESS) {
						if (method.equals("mdb_cursor_open")) {
							PointerBuffer handle = invocation.getArgument(2);
							cursorDatabases.put(handle.get(0), invocation.getArgument(1));
						} else if (method.equals("mdb_get")) {
							recordEntry(invocation.getArgument(1), invocation.getArgument(2),
									invocation.getArgument(3), metadataDbi, deltasDbi, directoryNode, direction);
						} else if (method.equals("mdb_cursor_get")) {
							Integer database = cursorDatabases.get((long) invocation.getArgument(0));
							if (database != null) {
								recordEntry(database, invocation.getArgument(1), invocation.getArgument(2),
										metadataDbi, deltasDbi, directoryNode, direction);
							}
						}
					} else if (outermost && method.equals("mdb_cursor_close")) {
						cursorDatabases.remove((long) invocation.getArgument(0));
					}
					return result;
				} finally {
					nativeDepth--;
				}
			});
			try {
				codecCalls = mockStatic(PersistentCsfPageCodec.class, invocation -> {
					boolean outermost = codecDepth++ == 0;
					try {
						Object result = invocation.callRealMethod();
						if (outermost && invocation.getMethod().getName().equals("decode")) {
							decodedPages++;
							decodedRows += ((DecodedPage) result).size();
						} else if (outermost && invocation.getMethod().getName().equals("probe")) {
							probedPages++;
						}
						return result;
					} finally {
						codecDepth--;
					}
				});
			} catch (RuntimeException | Error failure) {
				nativeCalls.close();
				throw failure;
			}
		}

		private void recordEntry(int database, MDBVal key, MDBVal value, int metadataDbi, int deltasDbi,
				long directoryNode, int direction) {
			ByteBuffer bytes = key.mv_data().duplicate().order(ByteOrder.BIG_ENDIAN);
			if (database == metadataDbi && bytes.remaining() == 18 && bytes.get(0) == 4
					&& bytes.getLong(2) == directoryNode && (bytes.get(1) & 1) == direction) {
				assertThat(value.mv_size()).isEqualTo(Long.BYTES);
				directoryPlanes.add(Byte.toUnsignedInt(bytes.get(1)));
			} else if (database == deltasDbi && bytes.remaining() == 33 && value.mv_size() == 1
					&& value.mv_data().get(0) == 0 && bytes.getLong(9) == directoryNode
					&& (bytes.get(0) & 1) == direction) {
				absentPlanes.add(Byte.toUnsignedInt(bytes.get(0)));
			}
		}

		@Override
		public void close() {
			try {
				codecCalls.close();
			} finally {
				nativeCalls.close();
			}
		}
	}
}
